"""Write reports/openweight_comparison_findings.md (D-10, pre-registration §7.5) from the generated files.

Every number comes from analysis/openweight/summary_<d>.json, analysis/openweight/o2/o2_<d>.json,
analysis/six_disease/o2/o2_<d>.json (Claude's O2, same harness and snapshot), runs/ow-<d>/manifest.json
and the failed-attempt logs beside it, analysis/openweight/gatekeeper_compare.json and the two
memorization-probe summaries (analysis/bias/memorization/{,openweight_}scores_summary.json). Prose that is not a number is written here once.

  uv run python analysis/openweight/report.py
"""
import json
from pathlib import Path

D = ["ha20", "ssadh"]
NAME = {"ha20": "A20 haploinsufficiency (HA20)", "ssadh": "SSADH deficiency"}


def j(p):
    return json.loads(Path(p).read_text())


def pct(x, nd=1):
    return "—" if x is None else f"{100 * x:.{nd}f}%"


def w(b):
    return "—" if not b or b.get("share") is None else f"{100 * b['share']:.1f}% ({b['k']}/{b['n']}; 95% CI {100 * b['ci95'][0]:.1f}–{100 * b['ci95'][1]:.1f})"


def failed_cost(d):
    """Host-reported cost of failed attempts that got as far as writing a usage line."""
    c = n = 0
    for f in Path(f"runs/ow-{d}/failed_attempts").glob("*.log"):
        last = [x for x in f.read_text(errors="replace").splitlines() if x.startswith('{"usage"')]
        if last:
            c += json.loads(last[-1]).get("cost_usd_reported") or 0
            n += 1
    return c, n, len(list(Path(f"runs/ow-{d}/failed_attempts").glob("*.log")))


def main():
    G = j("analysis/openweight/gatekeeper_compare.json")
    PC, PO = j("analysis/bias/memorization/scores_summary.json"), j("analysis/bias/memorization/openweight_scores_summary.json")
    FC = {d: failed_cost(d) for d in D}
    reported = sum(M_["final_attempts"]["cost_usd_reported_by_host"] for M_ in (j(f"runs/ow-{d}/manifest.json") for d in D)) + sum(c for c, _, _ in FC.values())
    S = {d: j(f"analysis/openweight/summary_{d}.json") for d in D}
    OC = {d: j(f"analysis/six_disease/o2/o2_{d}.json") for d in D}
    OO = {d: j(f"analysis/openweight/o2/o2_{d}.json") for d in D}
    M = {d: j(f"runs/ow-{d}/manifest.json") for d in D}
    key = M["ha20"]["key_spend_both_runs_usd"]
    L = ["# Claude vs an open-weight model on HA20 and SSADH deficiency (D-10)", "",
         "*Pre-registration §7.5 (O5, secondary). Generated by `analysis/openweight/report.py` from `analysis/openweight/summary_<d>.json`, "
         "`analysis/openweight/o2/`, `analysis/six_disease/o2/`, `runs/ow-<d>/`, `analysis/openweight/gatekeeper_compare.json` and the memorization-probe summaries. Run date 2026-10-21. "
         "HA20 is a development disease (D-18); SSADH deficiency is not.*", "",
         "## 1. What ran", "",
         f"- **Open-weight model:** `{M['ha20']['model']}` (DeepSeek-V4.1-Flash, 2026-09-10 checkpoint) through `{M['ha20']['endpoint']}`, "
         f"provider pinned to `{M['ha20']['provider_pinned']}` with fallbacks off. Every final attempt was served by "
         f"{', '.join(sorted(set(M['ha20']['served_by_final_attempts']) | set(M['ssadh']['served_by_final_attempts'])))}.",
         "- **Claude:** the frozen six-disease run (`pv1-ha20`, `pv1-ssadh`), Claude Code helper agents (D-17, D-20).",
         f"- **Same inputs:** the same papers ({M['ha20']['papers']} HA20, {M['ssadh']['papers']} SSADH), the same launch prompt (copied from the pv1 helpers), "
         "and the same instruction, schema and rules files, unchanged from the frozen commit (`ef3133e`) and the D-38 per-disease copies. "
         "Hashes are in each manifest.",
         "- **Same scoring:** both runs went through the same span check, reconciliation (merge policy v4), VariantValidator normalization and "
         "O2 harness (ClinVar snapshot 2026-10-19), with no gatekeeper filtering on either side.",
         f"- **Spend:** between **${reported:.2f}** and **${key['spent']:.2f}**, billed to OpenRouter, not the award (`BUDGET.md`). "
         f"The host reported ${M['ha20']['final_attempts']['cost_usd_reported_by_host']:.2f} (HA20) and ${M['ssadh']['final_attempts']['cost_usd_reported_by_host']:.2f} (SSADH) "
         f"for final attempts, plus ${sum(c for c, _, _ in FC.values()):.2f} for the {sum(n for _, n, _ in FC.values())} failed attempts that logged usage; "
         f"{sum(t - n for _, n, t in FC.values())} failed attempts stopped before logging any. The key's usage rose ${key['start']:.2f} → ${key['end']:.2f} "
         f"(${key['spent']:.2f}) over the runs, but the key is shared with other projects in the same environment (`DECISIONS.md`, 2026-10-21), "
         "so that rise is an upper bound.", "",
         "## 2. Registered metrics", "",
         "| Metric | HA20 Claude | HA20 open-weight | SSADH Claude | SSADH open-weight |", "|---|---|---|---|---|"]

    def row(name, f):
        L.append(f"| {name} | " + " | ".join(f"{f(d, 'claude')} | {f(d, 'open')}" for d in D) + " |")

    row("Papers", lambda d, k: S[d]["papers_compared"])
    row("Values asserted", lambda d, k: f"{S[d]['span'][k]['values_asserted']:,}")
    row("**Span-not-found rate**", lambda d, k: f"**{pct(S[d]['span'][k]['span_not_found_rate'], 2)}**")
    row("… quote given but not in the paper", lambda d, k: f"{pct(S[d]['span'][k]['quote_not_in_paper_rate'], 2)} ({S[d]['span'][k]['quote_not_in_paper']:,})")
    row("… no quote given", lambda d, k: f"{pct(S[d]['span'][k]['no_quote_rate'], 2)} ({S[d]['span'][k]['no_quote']:,})")
    row("Cells not in the schema's {value, span} shape", lambda d, k: S[d]["span"][k]["cells_not_in_schema_shape"])
    o2 = lambda d, k: OC[d] if k == "claude" else OO[d]
    row("**HGVS recall, tiers 1+2** (§7.2.2)", lambda d, k: w(o2(d, k)["all_papers"]["hgvs_recall_tier12"]))
    row("HGVS recall, tier 1", lambda d, k: w(o2(d, k)["all_papers"]["hgvs_recall_tier1"]))
    row("Overlap with ClinVar, tier 1 (not precision)", lambda d, k: w(o2(d, k)["all_papers"]["overlap_tier1"]))
    row("Classification agreement, where the paper states one", lambda d, k: w(o2(d, k)["all_papers"]["classification_agreement_among_stated"]))
    row("Overlap, tier 1, without ClinVar-cited papers (D-19)", lambda d, k: w(o2(d, k)["without_clinvar_cited_papers_D19"]["overlap_tier1"]))
    row("Individuals (coverage)", lambda d, k: f"{S[d]['coverage'][k]['individuals']:,}")
    row("Identities after merging", lambda d, k: f"{j(f'data/extracted/{d}/' + ('pv1' if k == 'claude' else 'ow') + f'-{d}/reconcile_summary.json')['identities_after_merging']:,}")
    row("Target-gene variants (distinct per paper)", lambda d, k: f"{S[d]['coverage'][k]['target_gene_variant_keys']:,}")
    row("Phenotypic-feature rows", lambda d, k: f"{S[d]['coverage'][k]['phenotypic_feature_rows']:,}")
    row("Checklist cells observed or excluded", lambda d, k: f"{S[d]['coverage'][k]['checklist_cells_observed_or_excluded']:,}")
    row("**Cost per paper, median**", lambda d, k: f"**${S[d]['cost_usd']['claude_median_per_paper' if k == 'claude' else 'open_median_per_paper']:.2f}**")
    row("Cost, all papers", lambda d, k: f"${S[d]['cost_usd']['claude_estimate_total' if k == 'claude' else 'open_reported_total']:.2f}")
    row("**Wall-clock per paper, median**", lambda d, k: f"**{S[d]['wall_seconds']['claude_median' if k == 'claude' else 'open_median'] / 60:.1f} min**")
    L += ["", "- **Unsupported rate on a blinded audit sample (§7.5):** not yet measured. It needs equal-size samples from each model, rated blind; "
          "the size waits on D-11 (panel hours). §6 gives the gatekeeper's reading in the meantime.",
          "- **Recall without ClinVar-cited papers (D-19)** is undefined: every reference pair comes from a paper ClinVar cites. The D-19 row gives overlap instead.",
          "- **Cost:** Claude's figure is an estimate (helper tokens × $5.996 per weighted million, the rate the session readings gave for the six-disease run). "
          "The open-weight figure is what the host reported for the final attempt of each paper.",
          "- **Wall-clock:** both ran about 10 papers at a time. The open-weight figure depends on one provider's throughput and includes waits after dropped connections.", "",
          "## 3. Agreement between the two models (descriptive)", "",
          "| | HA20 | SSADH |", "|---|---|---|",
          "| Target-gene variant keys, shared / union | " + " | ".join(
              f"{S[d]['variant_keys']['shared']}/{S[d]['variant_keys']['union']} ({pct(S[d]['variant_keys']['jaccard_pooled'])}); Claude only {S[d]['variant_keys']['claude_only']}, open-weight only {S[d]['variant_keys']['open_only']}" for d in D) + " |",
          "| Checklist status agreement on shared cells | " + " | ".join(f"{pct(S[d]['checklist']['status_agreement'])} of {S[d]['checklist']['cells_shared']:,}" for d in D) + " |", "",
          "## 4. How the scaffolds differed", "",
          "Stated as the plan requires (§7.5). Claude's helpers ran in Claude Code; the open-weight model ran in `pipeline/extract/openweight/agent.py`.", "",
          "- **No shell.** The open-weight loop had file tools only: read, grep, glob, write and edit, with the same read and write limits. "
          "Claude's helpers also had a shell, which they used for small checking scripts, and Claude Code's own system prompt.",
          "- **Harness fixes during the run** (approved by Dr. Lin, 2026-10-21; `DECISIONS.md`, D-10 OpenRouter entry):",
          "  - retries after dropped connections and 5xx errors;",
          "  - v2: a write to a `.json` file reports whether it parses. The frozen instructions ask for that check, and Claude's helpers made it with the shell;",
          "  - v3: a reply cut off at the output limit is followed by a request to resume.",
          f"- **Which harness version made each final output:** HA20 {', '.join(f'{k} {v}' for k, v in sorted(M['ha20']['tools_version_of_final_attempt'].items()))}; "
          f"SSADH {', '.join(f'{k} {v}' for k, v in sorted(M['ssadh']['tools_version_of_final_attempt'].items()))}. "
          f"The resume request (v3) was never needed: {M['ha20']['final_attempts']['resumes_after_cut_off_reply'] + M['ssadh']['final_attempts']['resumes_after_cut_off_reply']} resumes.",
          f"- **Failed attempts:** {len(M['ha20']['papers_with_failed_attempts'])} HA20 papers and {len(M['ssadh']['papers_with_failed_attempts'])} SSADH {'paper' if len(M['ssadh']['papers_with_failed_attempts']) == 1 else 'papers'} were re-run from a clean start. "
          "The failures were dropped connections, one output that did not parse, and four replies cut off before any file was written. "
          "Each failed attempt is kept in `runs/ow-<d>/failed_attempts/`.",
          f"- **Retried calls in final attempts:** HA20 {M['ha20']['final_attempts']['retried_calls']}, SSADH {M['ssadh']['final_attempts']['retried_calls']}.", "",
          "## 5. Reading the results", ""]
    nq = {d: S[d]["span"]["open"]["no_quote_rate"] for d in D}
    cm = {d: S[d]["cost_usd"]["claude_median_per_paper"] / S[d]["cost_usd"]["open_median_per_paper"] for d in D}
    claude_total = sum(S[d]["cost_usd"]["claude_estimate_total"] for d in D)
    n_papers = sum(S[d]["papers_compared"] for d in D)
    wm = {d: S[d]["wall_seconds"]["open_median"] / S[d]["wall_seconds"]["claude_median"] for d in D}
    ph = {d: S[d]["coverage"]["open"]["phenotypic_feature_rows"] / S[d]["coverage"]["claude"]["phenotypic_feature_rows"] for d in D}
    L += [f"- **Provenance:** every value Claude asserted had a quote found in the paper. The open-weight model gave no quote for "
          f"{pct(nq['ha20'])} (HA20) and {pct(nq['ssadh'])} (SSADH) of its values. When it gave one, the quote was almost always in the paper.",
          "- **Variants:** the two models found largely the same target-gene variants (§3). Claude's HGVS recall against ClinVar was higher on HA20 "
          "and about the same on SSADH; the denominators are small and the intervals overlap.",
          f"- **Phenotypes:** the open-weight model wrote {pct(ph['ha20'], 0)} (HA20) and {pct(ph['ssadh'], 0)} (SSADH) as many phenotypic-feature rows as Claude. "
          "Checklist cells marked observed or excluded were slightly more numerous for the open-weight model.",
          f"- **Cost:** per paper, the median open-weight cost was 1/{cm['ha20']:.0f} (HA20) and 1/{cm['ssadh']:.0f} (SSADH) of Claude's estimated cost. "
          f"Counted with failed attempts, the open-weight runs cost ${reported:.2f} to ${key['spent']:.2f} for {n_papers} papers (§1), against Claude's ${claude_total:.2f} estimate "
          f"(1/{claude_total / reported:.1f} to 1/{claude_total / key['spent']:.1f}).",
          f"- **Time:** the median open-weight paper took {wm['ha20']:.1f}× (HA20) and {wm['ssadh']:.1f}× (SSADH) as long as Claude's.",
          f"- **Support (gatekeeper, §6):** the same Claude gatekeeper judged {pct(G['ha20']['open']['unsupported']['share'])} (HA20) and {pct(G['ssadh']['open']['unsupported']['share'])} (SSADH) "
          f"of the open-weight model's claims unsupported, against {pct(G['ha20']['claude']['unsupported']['share'])} and {pct(G['ssadh']['claude']['unsupported']['share'])} of Claude's. "
          "Most of the gap is claims with no quote, but claims with a quote were also judged unsupported more often: "
          + ", ".join(f"{G[d]['open']['by_span']['quote']['unsupported']['share'] / G[d]['claude']['by_span']['quote']['unsupported']['share']:.0f}× ({d.upper()})" for d in D) + " Claude's rate.",
          "- **Not yet measured:** whether a value is right as a person reads it. That is the blinded audit (§2).",
          "- **Scope:** two diseases, one open-weight model, one provider. These are not general findings."]
    L += ["", "## 6. Gatekeeper reading on both runs", "",
          "Approved by Dr. Lin on 2026-10-21 (gatekeeper line; `DECISIONS.md`). The frozen gatekeeper v4 judged the open-weight run's claims with the same "
          "instructions, launch prompt and helper setup as the pv1 runs: Claude Code helpers, one per chunk, reading only the instructions, the claims and the paper. "
          "Claims are numbered and classed by the same prep script. Model claims only (the ones a helper judges); exact 95% intervals.", "",
          "| Measure | HA20 Claude | HA20 open-weight | SSADH Claude | SSADH open-weight |", "|---|---|---|---|---|"]
    g = lambda d, k: G[d]["claude" if k == "claude" else "open"]
    ci = lambda r: "—" if not r else f"{100 * r['share']:.2f}% ({100 * r['ci95'][0]:.2f}–{100 * r['ci95'][1]:.2f})"
    row("Model claims judged", lambda d, k: f"{g(d, k)['model_claims']:,}")
    for v in ("supported", "partially_supported", "unsupported", "span_not_found"):
        row(v.replace("_", " ").capitalize(), lambda d, k, v=v: f"{g(d, k)['verdicts'][v]:,}")
    row("**Unsupported rate**", lambda d, k: f"**{ci(g(d, k)['unsupported'])}**")
    row("Anything but supported", lambda d, k: ci(g(d, k)["not_supported"]))
    row("Claims with an empty quote", lambda d, k: f"{g(d, k)['by_span']['empty']['claims']:,}")
    row("… judged unsupported", lambda d, k: f"{g(d, k)['by_span']['empty']['unsupported']['k']:,}" if g(d, k)["by_span"]["empty"]["unsupported"] else "0")
    row("Unsupported rate, claims with a quote", lambda d, k: ci(g(d, k)["by_span"]["quote"]["unsupported"]))
    row("Papers with an unsupported claim", lambda d, k: g(d, k)["papers_with_unsupported"])
    top = lambda d, k: "; ".join(f"`{f}` {n}" for f, n in g(d, k)["unsupported_top_fields"][:4])
    L += ["", "Fields with most unsupported claims:", ""] + [f"- {d.upper()} {lab}: {top(d, k)}" for d in D for k, lab in (("claude", "Claude"), ("open", "open-weight"))]
    L += ["", "How to read it:", "",
          "- **The judge is Claude.** A Claude gatekeeper judging a Claude extraction and a non-Claude extraction may not be neutral. "
          "The blinded human audit (§2) is what settles support; this table is the gatekeeper's reading only.",
          "- **Empty quotes.** Claude's helpers left no asserted value without a quote. In a handful of pv1 papers that was after a repair-only resume of a helper "
          "that had left quotes empty (`reports/six_disease_run_findings.md`). The open-weight run had no repair pass. That is a scaffold difference, stated here as §7.5 asks.",
          f"- **Empty quotes were not judged the same way by every helper.** Gatekeeper v4 says a value needs its own quote. Most helpers judged an empty-quote claim unsupported "
          f"({G['ha20']['open']['by_span']['empty']['unsupported']['k']:,} of {G['ha20']['open']['by_span']['empty']['claims']:,} HA20, "
          f"{G['ssadh']['open']['by_span']['empty']['unsupported']['k']:,} of {G['ssadh']['open']['by_span']['empty']['claims']:,} SSADH). "
          f"Some judged it against the quote on the same row and called it supported ({G['ha20']['open']['by_span']['empty']['supported']:,} HA20, "
          f"{G['ssadh']['open']['by_span']['empty']['supported']:,} SSADH) or partially supported. So the open-weight unsupported rate is, if anything, a little low.",
          f"- **Quotes not in the paper:** {G['ha20']['open']['quote_not_found_by_span_check']['claims']} HA20 and {G['ssadh']['open']['quote_not_found_by_span_check']['claims']} SSADH model claims "
          "had a quote the span check did not find (the rest of §2's count are bookkeeping fields). Helpers marked "
          f"{G['ha20']['open']['quote_not_found_by_span_check']['span_not_found']} and {G['ssadh']['open']['quote_not_found_by_span_check']['span_not_found']} of them span not found "
          "and judged the others against near-matching text. Gatekeeper v4 tells helpers that a script has confirmed every quote verbatim; that held for every Claude claim "
          "but not for these, because the prep script does not drop them. The verdicts stand in this table; §2 still counts these quotes as not found.",
          "- **Common open-weight failures, from the helpers' reasons:** `is_proband` = false with no quote; checklist statuses with no quote; a gene symbol quoted from a "
          "background sentence rather than the person's test result; an age at examination or presentation given as an onset age; parents' variant fields quoted from "
          "the proband's sentence; hedged findings (\"possible\", \"suspected\") recorded as observed.", "",
          "## 7. Memorization probe on both models", "",
          "Exploratory (§7.4.3). The same 180 papers and probe items as the Claude side (WS5), sent to the open-weight model with no tools and the items inline; "
          "the Claude helpers read the same items from a file. Run 2026-10-21, 12 calls, $0.05 on the OpenRouter key. Scored by the same script against the pv1 "
          "extraction, never against ClinVar or OMIM. Full tables: `analysis/bias/memorization/scores_summary.md` (Claude) and `openweight_scores_summary.md`.", "",
          "| Measure, all 180 papers | Claude | Open-weight |", "|---|---|---|"]
    tot = lambda P, f: sum(P["by_stratum"][s][f] for s in P["by_stratum"])
    for lab, f in (("Closed-book answers marked specific", "cb_specific"), ("… marked guess", "cb_guess"), ("… marked none", "cb_none"),
                   ("Papers with a variant hit", "cb_papers_with_variant_hit"), ("Variants given (hits)", None),
                   ("Phenotype terms given / matching the paper", None), ("Completions with a run of 8+ words from the paper", "cp_papers_run_ge_8")):
        if f:
            L.append(f"| {lab} | {tot(PC, f)} | {tot(PO, f)} |")
        elif lab.startswith("Variants"):
            L.append(f"| {lab} | {tot(PC, 'cb_variants_given')} ({tot(PC, 'cb_variant_hits')}) | {tot(PO, 'cb_variants_given')} ({tot(PO, 'cb_variant_hits')}) |")
        else:
            L.append(f"| {lab} | {tot(PC, 'cb_phen_given')} / {tot(PC, 'cb_phen_hits')} | {tot(PO, 'cb_phen_given')} / {tot(PO, 'cb_phen_hits')} |")
    L.append("| Longest run from the paper, max (words) | " + f"{max(PC['by_stratum'][s]['cp_max_longest_run'] for s in PC['by_stratum'])} | "
             f"{max(PO['by_stratum'][s]['cp_max_longest_run'] for s in PO['by_stratum'])} |")
    L += ["", "- Neither model showed recall of these papers' variants: a handful of variant hits each, the kind a guess from the title or the gene's best-known variant gives.",
          "- The open-weight model more often answered \"none\". Claude guessed more phenotypes, and more of them matched the paper, which is what general knowledge "
          "of the disease predicts; it is not evidence of recall of the paper.",
          "- The strata (before or after a training cutoff) were set from Claude's cutoff. The open-weight checkpoint's cutoff is not known here, so its strata carry no meaning.",
          f"- This probe does not explain the support gap in §6: neither model reproduced the papers' variants, and the longest run of the papers' own words in a "
          f"completion was {max(PC['by_stratum'][s]['cp_max_longest_run'] for s in PC['by_stratum'])} words (Claude) and {max(PO['by_stratum'][s]['cp_max_longest_run'] for s in PO['by_stratum'])} (open-weight)."]
    Path("reports/openweight_comparison_findings.md").write_text("\n".join(L) + "\n")
    print("\n".join(L))


if __name__ == "__main__":
    main()
